import { validateThemeOptions } from '@game-studio/operator-theme';
import { VueConstructor } from 'vue';
import './assets/styles/overlays.scss';
import BonusInPlay from './components/bonus-in-play/index.vue';
import CooloffWindow from './components/cooloff-window/index.vue';
import DemoMessaging from './components/demo-messaging/index.vue';
import ErrorSplash from './components/error-splash/index.vue';
import FreePlay from './components/free-play/index.vue';
import GameInGameFreeze from './components/game-in-game-freeze/index.vue';
import IdVerification from './components/id-verification/index.vue';
import InvalidStake from './components/invalid-stake/index.vue';
import LoadingSpinner from './components/loading-spinner/index.vue';
import LoadingSplash from './components/loading-splash/index.vue';
import LowFunds from './components/low-funds/index.vue';
import NicknameOverlay from './components/nickname/index.vue';
import Popup from './components/popup/index.vue';
import './components/promo-view/index.vue';
import PromoView from './components/promo-view/index.vue';
import RealityCheck from './components/reality-check/index.vue';
import SocialShare from './components/social-share/index.vue';
import TimeKeeper from './components/time-keeper/index.vue';
import TimeLimitReachedWindow from './components/time-limit-reached/index.vue';
import Toast from './components/toast/index.vue';
import './components/top-prize/index.vue';
import TopPrize from './components/top-prize/index.vue';
import './components/wallet-popup/index.vue';
import WalletPopup from './components/wallet-popup/index.vue';
import { OPTIONS } from './options';
import { IOverlaysPluginOptions } from './types';
import AutoWithdraw from './components/auto-withdraw/index.vue';
import SessionManagement from './components/session-manager/index.vue';
import SelfExclusion from './components/self-exclusion/index.vue';
import SessionAlerts from './components/session-alerts/index.vue';

class Overlays {
    private installed: boolean = false;

    public install(Vue: VueConstructor, options: IOverlaysPluginOptions) {
        if (!options) {
            throw new Error('@game-studio/overlays requires IOverlaysPluginOptions to be provided');
        }

        if (typeof options.logoBase64 !== 'string') {
            throw new Error('@game-studio/overlays requires a valid "logoBase64"');
        }

        try {
            validateThemeOptions(options.theme);
        } catch (error: any) {
            throw new Error(`@game-studio/overlays theme config invalid "${error.message}"`);
        }

        if (this.installed) {
            return;
        }

        Vue.component('id-verification', IdVerification);
        Vue.component('loading-spinner', LoadingSpinner);
        Vue.component('low-funds', LowFunds);
        Vue.component('reality-check', RealityCheck);
        Vue.component('social-share', SocialShare);
        Vue.component('time-keeper', TimeKeeper);
        Vue.component('toast', Toast);
        Vue.component('free-play', FreePlay);
        Vue.component('popup', Popup);
        Vue.component('top-prize', TopPrize);
        Vue.component('promo-view', PromoView);
        Vue.component('demo-messaging', DemoMessaging);
        Vue.component('bonus-in-play', BonusInPlay);
        Vue.component('loading-splash', LoadingSplash);
        Vue.component('error-splash', ErrorSplash);
        Vue.component('cooloff-window', CooloffWindow);
        Vue.component('time-limit-reached-window', TimeLimitReachedWindow);
        Vue.component('game-in-game-freeze', GameInGameFreeze);
        Vue.component('nickname-overlay', NicknameOverlay);
        Vue.component('invalid-stake', InvalidStake);
        Vue.component('wallet-popup', WalletPopup);
        Vue.component('auto-withdraw', AutoWithdraw);
        Vue.component('session-management', SessionManagement);
        Vue.component('self-exclusion', SelfExclusion);
        Vue.component('session-alerts', SessionAlerts);
        Object.assign(OPTIONS, options);

        this.installed = true;
    }
}

export * from './components/nickname/types';
export * from './components/session-manager/types';
export { default as BasicSessionDataVue } from './components/session-data/basic/index.vue';
export { default as ESSessionDataVue } from './components/session-data/es/index.vue';
export { default as ITSessionDataVue } from './components/session-data/it/index.vue';
export { default as UKSessionDataVue } from './components/session-data/uk/index.vue';
export { OverlaysEventEmitter } from './event-emitter';
export * from './types';
export default new Overlays();

